import{_ as o,o as r,c as e,ag as n}from"./chunks/framework.DzGOF12C.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"문제의식: 우주(현상세계)는 객관적 실재인가?","slug":"문제의식-우주-현상세계-는-객관적-실재인가","link":"#문제의식-우주-현상세계-는-객관적-실재인가","children":[]},{"level":2,"title":"불교는 리를 부정한다","slug":"불교는-리를-부정한다","link":"#불교는-리를-부정한다","children":[]},{"level":2,"title":"정도전의 기(氣)·리(理)·심(心) 개념","slug":"정도전의-기-氣-·리-理-·심-心-개념","link":"#정도전의-기-氣-·리-理-·심-心-개념","children":[]},{"level":2,"title":"심·성·정의 관계","slug":"심·성·정의-관계","link":"#심·성·정의-관계","children":[]}],"relativePath":"philosophy/Korean-Philosophy/07. 정도전.md","filePath":"philosophy/Korean-Philosophy/07. 정도전.md"}'),a={name:"philosophy/Korean-Philosophy/07. 정도전.md"};function s(l,t,i,u,p,h){return r(),e("div",null,[...t[0]||(t[0]=[n('<h2 id="문제의식-우주-현상세계-는-객관적-실재인가" tabindex="-1">문제의식: 우주(현상세계)는 객관적 실재인가? <a class="header-anchor" href="#문제의식-우주-현상세계-는-객관적-실재인가" aria-label="Permalink to &quot;문제의식: 우주(현상세계)는 객관적 실재인가?&quot;">​</a></h2><p>우주는 감각기관을 통해 마주하는 가시적 현상세계의 총체이며, 그 자체의 원리·법칙에 따라 운행되고 인간 역시 그 일원으로서 자연의 인과적 필연성에 지배받는 유한한 존재다. 그런데 인간이 경험하는 이 현상세계가 인간의 마음과 <strong>독립적으로 존재하는 객관적 실재</strong>라면, 인간은 그 질서와 법칙에 규정되는 존재일 수밖에 없다. 반대로 현상세계가 우리 마음을 떠난 객관적 실재가 아니라 오히려 마음에 의해 그런 모습으로 현현·질서지워진 가상적 존재일 뿐이라면, 그런 마음은 현상을 초월하는 능력을 가진 것으로 간주될 수 있다. 정도전은 성리학의 <strong>리(理)의 객관성</strong>과 <strong>현상세계의 실재성</strong>을 근거로, 이 문제에 대한 불교의 답을 정면으로 비판한다.</p><h2 id="불교는-리를-부정한다" tabindex="-1">불교는 리를 부정한다 <a class="header-anchor" href="#불교는-리를-부정한다" aria-label="Permalink to &quot;불교는 리를 부정한다&quot;">​</a></h2><p>『불씨잡변』과 『심기리편』에서 정도전은 이렇게 말한다.</p><blockquote><p>&quot;심(心)이란 것은 사람이 하늘에서 얻어 태어난 기(氣)로서 허령불매(虛靈不昧)하여 한 몸의 주인이 된다. 성(性)이란 것은 사람이 하늘에서 얻어서 태어난 리(理)로서 순수하고 지극히 선한 것으로서 마음속에 갖추어져 있다.&quot;(『불씨잡변』)</p></blockquote><p>정도전에 따르면 사람이 존재하기 이전에 이미 리와 기가 존재하며, 리는 모든 존재가 따라야 할 <strong>객관적 법칙</strong>이다. 반면 &quot;석씨(불교)는 리가 심 속에 갖추어져 있다는 사실을 알지 못하고 심을 종주로 삼는다&quot;(『심기리편』) — 즉 불교는 심을 리보다 앞세우는데, 이는 결국 리가 심에 의해 만들어진다고 보는 것이므로 심 밖의 리·인륜·질서를 실재하는 것으로 인정하지 않는 셈이다. 리의 객관성과 현상세계의 실재성, 나아가 인간의 도덕성까지 부정되어버리면 세상은 가상적 세계가 되어버린다는 것이 정도전의 핵심 비판이다.</p><p><strong>&#39;일체유심조&#39;를 어떻게 볼 것인가?</strong> &quot;모든 것은 마음이 만들어낸 것이다&quot;라는 불교의 명제를, 마음 밖 대상의 존재 자체를 부정하는 존재론적 독단으로 읽어야 할까? 강의는 이를 &quot;마음 밖의 대상이라 하더라도 &#39;그것이 존재한다는 사실&#39;은 마음을 통해서만 드러난다&quot;는 뜻, 즉 우리가 접하는 세계는 이미 마음의 구조가 개입된 &#39;표상된 세계&#39;라는 뜻으로 이해하는 것이 더 설득력 있다고 본다. 이는 &quot;마음에 의존해야만 대상이 존재한다&quot;(마음이 없으면 대상도 없다는 강한 관념론)는 말과는 구분되어야 하며, 무엇이 있지도 않은데 마음이 모든 것을 만들어냈다고 하면 허무주의로 빠지게 되는데 이는 불교 스스로도 경계한 지점이다.</p><h2 id="정도전의-기-氣-·리-理-·심-心-개념" tabindex="-1">정도전의 기(氣)·리(理)·심(心) 개념 <a class="header-anchor" href="#정도전의-기-氣-·리-理-·심-心-개념" aria-label="Permalink to &quot;정도전의 기(氣)·리(理)·심(心) 개념&quot;">​</a></h2><p><strong>기</strong>: &quot;사람과 만물은 모두 천지의 기에 의해서 생겨난다&quot;(『불씨잡변』). 기가 응취(凝聚)하면 형질과 신기(神氣)가 되며, 기의 모임과 흩어짐으로 존재물은 생멸한다. &quot;하늘과 땅 사이는 용광로와 같아 비록 생물이라 할지라도 모두 다 녹아 없어진다. 어찌 이미 흩어진 것이 다시 합해지며, 이미 간 것이 다시 올 수 있겠는가?&quot; — 흩어진 기는 사라지고 새롭게 생성된 기가 새로운 존재를 생성하므로, 현상세계에 무엇이 존재하려면 반드시 기의 작용이 필요하다는 것이 성리학의 기론이다. 기는 음양·오행으로 표현되며 그 전개·운행에 의해 사계절이 펼쳐지고 우주가 운행된다.</p><p><strong>리</strong>: 그렇다면 기는 자기 멋대로 운행하는 것일까? 정도전은 그렇지 않다고 답한다 — &quot;리에 동정의 원리가 있기 때문에 기가 동정할 수 있다. 만약 리에 동정의 원리가 없다면 기가 어떻게 스스로 동정할 수 있겠는가?&quot;(『주자대전』) 즉 <strong>리=태극=도=성=형이상자</strong>, <strong>기=음양=오행=형이하자</strong>의 구도다. &quot;심신에는 심신의 도가 있어 가까이는 부자·군신·부부·장유·붕우에서부터 멀리는 천지만물에 이르기까지 각각 그 도가 있지 않음이 없다&quot;(『불씨잡변』) — 우주의 보편적 법칙(리)은 우주 운행의 길이자, 인간에게 내재된 것으로서 인간의 본성이 된다. 따라서 인간은 자신의 본성에 따라 살아가야 하며, 그 본성에 따른 규칙이 곧 <strong>인륜법칙</strong>이다.</p><p><strong>심</strong>: &quot;마음은 신명(神明)의 집이며, 성은 거기에 갖추어진 리이다&quot;(『불씨잡변』). 기의 모임으로 인간이 탄생하는데, 기는 자기 멋대로 모이는 것이 아니라 리의 인도에 따라 모이므로 <strong>인간은 리와 기의 결합물</strong>이다. 인간은 자신에게 부여된 본성(천지의 리)을 자각·실현해야 인간다운 존재가 될 수 있는데, 그 리를 자각할 수 있는 능력을 갖춘 기관이 바로 마음이다. 정도전에게 마음은 기본적으로 기이지만, 그 속에 리(智)가 부여되어 있기 때문에 인식 활동을 수행할 수 있다. 반면 불교는 리가 독립된 실체로 마음속에 내재하지 않는다고 보기 때문에, 정도전이 보기에 불교의 마음은 길을 잃고 사욕으로 치달을 수밖에 없다.</p><h2 id="심·성·정의-관계" tabindex="-1">심·성·정의 관계 <a class="header-anchor" href="#심·성·정의-관계" aria-label="Permalink to &quot;심·성·정의 관계&quot;">​</a></h2><p>&quot;마음에는 체와 용이 있다. &#39;미발&#39;한 상태는 마음의 체이고, &#39;이발&#39;한 상태는 마음의 용이니… 대개 주재하고 운용하는 것이 바로 마음이고, 성은 바로 그렇게 할 수 있는 이치이다. 성은 틀림없이 마음속에 있지만, 주재하고 운용하는 것은 마음에 달려 있다. 정은 단지 몇 갈래의 길이며, 그러한 길을 따라서 그렇게 만들어가는 것은 오히려 마음이다.&quot; 여기에 『중용』의 유명한 구절이 덧붙는다 — &quot;희로애락이 아직 발하지 않은 것을 **중(中)**이라 하고, 발하여 모두 절도에 맞는 것을 **화(和)**라 한다. 중은 천하의 큰 근본이요, 화는 천하에 통달한 도이다. 중화를 지극히 하면 천지가 제자리를 잡고 만물이 길러진다.&quot;</p><p>정리하면 <strong>심통성정</strong>(心統性情, 마음이 성과 정을 포괄·주재함) — <strong>성즉리</strong>(性卽理, 성은 사람의 본성인데 그것이 바로 리다) — <strong>성발위정</strong>(性發爲情, 정은 성이 기에 의해 외부로 발현된 것이다)이라는 구도로, 이는 정도전이 확립한 조선 성리학의 기본 틀이자 이후 사단칠정논쟁·인심도심논쟁이 전개되는 공통의 출발점이 된다.</p>',14)])])}const c=o(a,[["render",s]]);export{q as __pageData,c as default};
